"""ARTIFICIAL compilation only. No real artifacts are generated by these tests."""

import json
from copy import deepcopy

import pytest

from compilation_fixtures import SCHEMAS, compilation_inputs
from fyp_evaluation.authoring.compile import compile_ground_truth
from fyp_evaluation.validation.schemas import validate


def test_primary_acceptance_determinism_and_verbatim_copies():
    inputs = compilation_inputs()
    before = deepcopy(inputs)
    config, plan, dialogue, *_ = inputs
    ground = compile_ground_truth(*inputs, schema_dir=SCHEMAS)
    assert validate(ground, "ground_truth", SCHEMAS) == []
    assert compile_ground_truth(*inputs, schema_dir=SCHEMAS) == ground
    assert inputs == before
    assert ground["metadata"] == config["metadata"]
    assert ground["metadata"] is not config["metadata"]
    assert [turn["turn_id"] for turn in ground["dialogue"]] == list(range(len(dialogue["turns"])))
    assert all(type(turn["turn_id"]) is int for turn in ground["dialogue"])
    for source, output in zip(dialogue["turns"], ground["dialogue"]):
        for key in ("text", "critical_tokens"):
            assert json.dumps(source[key], ensure_ascii=False).encode("utf-8") == json.dumps(output[key], ensure_ascii=False).encode("utf-8")
    for source, output in zip(plan["checks"], ground["checks"]):
        assert output["expected"] == source["expected"] and output["expected"] is not source["expected"]
        assert output["evidence_plan"] == source["evidence_plan"]
        if source["evidence_plan"]["mode"] == "absence":
            assert output["gold_evidence_turns"] == [] and output["gold_evidence_text"] == ""
    ground["dialogue"][1]["critical_tokens"].clear()
    assert inputs == before


@pytest.mark.parametrize("index,schema", [(0, "call_config"), (1, "check_plan"), (2, "dialogue")])
def test_each_mismatched_artifact_rejected_before_other_work(index, schema):
    inputs = compilation_inputs()
    inputs[index]["call_id"] = "CALL_998"
    assert validate(inputs[index], schema, SCHEMAS) == []
    with pytest.raises(ValueError, match="CALL_99[89].*CALL_99[89]"):
        compile_ground_truth(*inputs, schema_dir="NONEXISTENT_SCHEMA_DIRECTORY")


def test_unknown_column_rejected_before_other_work():
    inputs = compilation_inputs()
    for artifact in inputs[:3]:
        artifact["call_id"] = "CALL_997"
    with pytest.raises(ValueError, match="CALL_997: no column"):
        compile_ground_truth(*inputs, schema_dir="NONEXISTENT_SCHEMA_DIRECTORY")


@pytest.mark.parametrize("qid,wrong", [
    ("K01", "S0000001X"), ("FIX_DOB", "1 May 1983"),
    ("FIX_INSTRUMENT", "ARTIFICIAL Silver Basket"), ("FIX_CURRENCY", "GBP"),
    # Regression: a longer identifier containing the locked value as a
    # substring, and a compound day-word ("twenty first") containing the
    # locked day's own word ("first") as a suffix, must both be rejected.
    ("K01", "XS0000000X"), ("FIX_DOB", "the twenty first of May, nineteen eighty-two"),
])
def test_wrong_planned_value_rejected_even_with_exact_dialogue_match(qid, wrong):
    inputs = compilation_inputs()
    plan, dialogue = inputs[1:3]
    check = next(check for check in plan["checks"] if check["question_id"] == qid)
    item = check["evidence_plan"]["planned_evidence"][0]
    target = next(turn for turn in dialogue["turns"] if turn["text"] == item["text"])
    item["text"] = target["text"] = wrong
    target["critical_tokens"] = [wrong]
    with pytest.raises(ValueError, match=f"{qid}: planned evidence does not denote"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_spelled_identifiers_currency_and_dob_compile():
    inputs = compilation_inputs()
    plan, dialogue = inputs[1:3]
    for qid, text in (("K01", "S zero zero zero zero zero zero zero X"), ("FIX_CURRENCY", "E U R"),
                      ("FIX_DOB", "the first of May, nineteen eighty-two")):
        item = next(check for check in plan["checks"] if check["question_id"] == qid)["evidence_plan"]["planned_evidence"][0]
        target = next(turn for turn in dialogue["turns"] if turn["text"] == item["text"])
        item["text"] = target["text"] = text
        target["critical_tokens"] = [text]
    ground = compile_ground_truth(*inputs, schema_dir=SCHEMAS)
    assert validate(ground, "ground_truth", SCHEMAS) == []


@pytest.mark.parametrize("case", ["not_found", "ambiguous", "wrong_speaker", "reversed"])
def test_invalid_matching_refuses_compilation(case):
    inputs = compilation_inputs()
    plan, dialogue = inputs[1:3]
    if case == "not_found":
        dialogue["turns"][0]["text"] = "ARTIFICIAL other"
    elif case == "ambiguous":
        dialogue["turns"].append(deepcopy(dialogue["turns"][0]))
    elif case == "wrong_speaker":
        dialogue["turns"][0]["speaker"] = "CLIENT"
    else:
        evidence = plan["checks"][0]["evidence_plan"]["planned_evidence"]
        evidence[0]["text"] = "later marker"
        evidence.append({"evidence_id": "FIX_PRESENT_E2", "required_speaker": "EMPLOYEE", "text": "earlier marker"})
        dialogue["turns"][0]["text"] = "earlier marker"
        dialogue["turns"].append({"speaker": "EMPLOYEE", "text": "later marker", "critical_tokens": []})
    with pytest.raises(ValueError, match={"not_found": "not found", "ambiguous": "ambiguous",
                                         "wrong_speaker": "not found", "reversed": "order"}[case]):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


@pytest.mark.parametrize("same_turn", [True, False])
def test_multiple_items_union_and_plan_quote(same_turn):
    inputs = compilation_inputs()
    plan, dialogue = inputs[1:3]
    evidence = plan["checks"][0]["evidence_plan"]["planned_evidence"]
    evidence.append({"evidence_id": "FIX_PRESENT_E2", "required_speaker": "EMPLOYEE", "text": "ARTIFICIAL second marker"})
    if same_turn:
        dialogue["turns"][0]["text"] += " ARTIFICIAL second marker"
    else:
        dialogue["turns"].append({"speaker": "EMPLOYEE", "text": "ARTIFICIAL second marker", "critical_tokens": []})
    check = compile_ground_truth(*inputs, schema_dir=SCHEMAS)["checks"][0]
    assert check["gold_evidence_turns"] == ([0] if same_turn else [0, len(dialogue["turns"]) - 1])
    assert check["gold_evidence_text"] == "\n".join(item["text"] for item in evidence)


def test_one_turn_can_support_multiple_questions():
    inputs = compilation_inputs()
    config, plan, dialogue, checklist, normalization, matrix = inputs
    checklist.append({**checklist[0], "id": "FIX_SHARED"})
    for cells in matrix.values():
        cells["FIX_SHARED"] = "PASS"
    config["intended_answers"].append({**deepcopy(config["intended_answers"][0]), "question_id": "FIX_SHARED"})
    check = deepcopy(plan["checks"][0])
    check["question_id"] = "FIX_SHARED"
    check["evidence_plan"]["planned_evidence"][0]["evidence_id"] = "FIX_SHARED_E1"
    plan["checks"].append(check)
    ground = compile_ground_truth(*inputs, schema_dir=SCHEMAS)
    assert ground["checks"][0]["gold_evidence_turns"] == ground["checks"][-1]["gold_evidence_turns"] == [0]


def test_tampered_expected_rejected_even_if_all_other_artifacts_support_it():
    inputs = compilation_inputs()
    config, plan, dialogue = inputs[:3]
    for answers in (config["intended_answers"], plan["checks"]):
        answers[-1]["expected"]["expected_value"] = "GBP"
    phrase = plan["checks"][-1]["evidence_plan"]["planned_evidence"][0]
    phrase["text"] = dialogue["turns"][-1]["text"] = "GBP"
    dialogue["turns"][-1]["critical_tokens"] = ["GBP"]
    with pytest.raises(ValueError, match="matrix"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_independent_matrix_recheck_survives_bypassed_cross_file_validators(monkeypatch):
    # Exercise the independent compiler gate, not merely its validator's gate.
    import fyp_evaluation.authoring.compile as compiler
    inputs = compilation_inputs()
    inputs[1]["checks"][-1]["expected"]["expected_value"] = "GBP"
    monkeypatch.setattr(compiler, "validate_call_config", lambda *a, **k: [])
    monkeypatch.setattr(compiler, "validate_check_plan", lambda *a, **k: [])
    with pytest.raises(ValueError, match="value or type"):
        compiler.compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_independent_matrix_recheck_distinguishes_python_numeric_types(monkeypatch):
    import fyp_evaluation.authoring.compile as compiler
    inputs = compilation_inputs()
    inputs[4]["rules"]["fixture_integer"] = {"operation": "exact", "value_type": "integer"}
    inputs[4]["field_rules"]["fixture_currency"] = "fixture_integer"
    for cells in inputs[5].values():
        cells["FIX_CURRENCY"] = "7"
    inputs[1]["checks"][-1]["expected"] = {"kind": "extraction", "value_type": "integer", "expected_value": 7.0}
    monkeypatch.setattr(compiler, "validate_call_config", lambda *a, **k: [])
    monkeypatch.setattr(compiler, "validate_check_plan", lambda *a, **k: [])
    with pytest.raises(ValueError, match="value or type"):
        compiler.compile_ground_truth(*inputs, schema_dir=SCHEMAS)


@pytest.mark.parametrize("before,after,valid", [("FIX_PRESENT", "FIX_DOB", True),
                                               ("FIX_DOB", "FIX_PRESENT", False)])
def test_ordering_constraints(before, after, valid):
    inputs = compilation_inputs()
    inputs[1]["ordering_constraints"] = [{"before": before, "after": after}]
    if valid:
        assert compile_ground_truth(*inputs, schema_dir=SCHEMAS)
    else:
        with pytest.raises(ValueError, match="ordering_constraints"):
            compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_ordering_uses_last_before_turn_not_just_first():
    inputs = compilation_inputs()
    plan, dialogue = inputs[1:3]
    plan["checks"][0]["evidence_plan"]["planned_evidence"].append({
        "evidence_id": "FIX_PRESENT_E2", "required_speaker": "EMPLOYEE", "text": "ARTIFICIAL late marker"})
    dialogue["turns"].append({"speaker": "EMPLOYEE", "text": "ARTIFICIAL late marker", "critical_tokens": []})
    plan["ordering_constraints"] = [{"before": "FIX_PRESENT", "after": "FIX_DOB"}]
    with pytest.raises(ValueError, match="ordering_constraints"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_unicode_whitespace_and_annotation_order_are_preserved():
    inputs = compilation_inputs()
    text = "ARTIFICIAL café —  fee\n£250.50 at 3%."
    tokens = ["3%", "café", "£250.50", "fee"]
    inputs[2]["turns"].append({"speaker": "EMPLOYEE", "text": text, "critical_tokens": tokens})
    output = compile_ground_truth(*inputs, schema_dir=SCHEMAS)["dialogue"][-1]
    assert output["text"].encode("utf-8") == text.encode("utf-8")
    assert [token.encode("utf-8") for token in output["critical_tokens"]] == [token.encode("utf-8") for token in tokens]


def test_compiler_enforces_separate_annotation_gate():
    inputs = compilation_inputs()
    inputs[2]["turns"][-1]["critical_tokens"] = []
    with pytest.raises(ValueError, match="no critical token"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


def test_null_identifier_and_absence_patterns():
    inputs = compilation_inputs(null_identifier=True)
    ground = compile_ground_truth(*inputs, schema_dir=SCHEMAS)
    check = ground["checks"][2]
    assert check["expected"]["expected_value"] is None
    assert check["gold_evidence_turns"] == [] and check["gold_evidence_text"] == ""
    inputs[1]["checks"][2]["evidence_plan"]["forbidden_patterns"] = ["forbidden"]
    inputs[2]["turns"].append({"speaker": "CLIENT", "text": "ARTIFICIAL forbidden", "critical_tokens": []})
    with pytest.raises(ValueError, match="forbidden pattern"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)


@pytest.mark.parametrize("artifact", [0, 1])
def test_complete_mode_enforced(artifact):
    inputs = compilation_inputs()
    if artifact == 0:
        inputs[0]["scenario_facts"] = []
    else:
        inputs[1]["checks"][0]["evidence_plan"]["planned_evidence"][0]["text"] = "TODO_AUTHOR_PLANNED_EVIDENCE"
    with pytest.raises(ValueError, match="Incomplete"):
        compile_ground_truth(*inputs, schema_dir=SCHEMAS)
